window.DGNL_DE_MON["l10"] = {"id": "l10", "ten": "Đề thi thử số 10", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Motif tái sinh trong truyện cổ tích Tấm Cám thể hiện điều gì?", "choices": ["Khát vọng thay đổi thân phận trong xã hội", "Sự tồn tại bền bỉ của cái thiện trước cái ác", "Vai trò quyết định của yếu tố thần linh trong số phận con người", "Sự vận hành tuần hoàn của tự nhiên và đời sống con người"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Trống Trường Thành lung lay bóng </i><b><i>nguyệt</i></b><i>,</i><br><i>Khói Cam Tuyền mờ mịt thức mây.</i><br><i>Chín lần gươm báu trao tay,</i><br><i>Nửa đêm truyền hịch định ngày xuất chinh.</i><br>(Chinh phụ ngâm, Đặng Trần Côn, Phan Huy Ích dịch)<br>Theo đặc trưng thể thơ song thất lục bạn, từ in đậm hiệp vần với từ nào?", "choices": ["mịt", "thức", "mây", "tay"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đọc bài thơ sau<br><b>Ngôn hoài</b><br>Trạch đắc long xà địa khả cư,<br>Dã tình chung nhật lạc vô dư.<br>Hữu thì trực thướng cô phong đính,<br>Trường khiếu nhất thanh hàn thái hư.<br>(Không Lộ thiền sư)<br>Dịch nghĩa:<br><b>Tỏ lòng</b><br>Chọn được kiểu đất long xà rất hợp, có thể ở được,<br>Tình quê suốt ngày vui không chán.<br>Có lúc lên thẳng đỉnh núi bơ vơ,<br>Kêu dài một tiếng, lạnh cả bầu trời.<br><b>Phương án nào sau đây thể hiện rõ nhất tinh thần thơ thiền thời Trần qua bài thơ trên?</b>", "choices": ["Khắc họa cảnh thiên nhiên gắn với đời sống ẩn dật của con người", "Gợi lên trạng thái tâm hồn an nhiên, hòa hợp tuyệt đối với thiên nhiên", "Diễn tả trạng thái vừa thoát tục, vừa trần thế của con người", "Thể hiện khát vọng vượt lên thực tại để tìm kiếm ý nghĩa sống"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Được hỏi chuyện, Sạ trả lời dè dặt về quãng đời oanh liệt ông từng trải qua. Những lời đồn đại do gã buôn muối kể lại phần nào có thật. Người bản Hua Tát dựng lên cho Sạ một mái nhà sàn. Ông sống bình thường như mọi người khác. Có ai nhắc lại chuyện cũ thì ông lảng tránh. Sạ lấy vợ. Hai vợ chồng già sinh được một đứa con trai. Sống được đến bảy mươi tuổi thì ông mới mất. Trước khi mất, nghe đồn ông nói lại rằng: “Quãng đời bình thường cuối cùng ta sống ở bản Hua Tát như mọi người đời, mới thực chính là sự tích phi thường mà ta lập được.”</i><br><i>Có thể thế chăng? Không thấy người dân Hua Tát bàn tán gì về câu nói ấy. Nhưng đám tang Sạ, người ta cử hành trang trọng hệt như đám tang một vị vương hầu.”</i><br>(Sạ, Nguyễn Huy Thiệp, in trong Truyện ngắn Nguyễn Huy Thiệp, NXB Văn học, tr.30-32)<br>Đâu là nhận định <b>không</b> đúng về nhân vật Sạ?", "choices": ["Sạ có thái độ kín đáo về những trải nghiệm đã qua.", "Cuộc sống bình thường cuối đời cho thấy sự thay đổi trong nhận thức của Sạ về ý nghĩa của cuộc sống.", "Sạ được người dân Hua Tát ngưỡng mộ chính yếu vì ông đã sống một cuộc đời bình thường như mọi người.", "Có phần thêu dệt trong câu chuyện về Sạ."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Hai em </i><b><i>phương trưởng</i></b><i> hoà hai,</i><br><i>Nọ chàng Kim đó, là người ngày xưa!</i><br><i>Tưởng bây giờ là bao giờ,</i><br><i>Rõ ràng mở mắt, còn ngờ chiêm bao!</i><br>(Truyện Kiều, Nguyễn Du)<br>Từ “phương trưởng” có nghĩa là gì?", "choices": ["trưởng thành", "kết hôn", "sum họp", "hiếu thuận"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Thật vậy, bao nhiêu sách vở của loài người, cốt để dạy cho nhau biết mà thôi, vậy mà vẫn công toi cả. Những điều người ta dạy bảo nhau bằng sách ? Đó là những điều mơ hồ, những điều lầm lẫn, những sự văn chương. Văn chương là một sự, sự đời là một sự khác.</i><br><i>Rồi tôi cảm thấy rằng muốn làm một nhà xã hội học, một nhà tâm lý học, một nhà triết học thì trước hết hãy đăng vào nghề cơm thầy cơm cô. Người phu xe biết hết mọi sự độc ác của loài người hơn là một nhà học giả [...] Và một kẻ đi ở thì cũng biết rõ những tính tình của loài người hơn là một nhà văn sĩ tả chân.</i><br><i>(Cơm thầy cơm cô, Vũ Trọng Phụng)</i><br>Đâu là nhận định <b>không</b> được đề cập trong đoạn trích trên?", "choices": ["Việc hiểu biết con người và xã hội không thể chỉ dựa vào sách vở.", "Trải nghiệm đời sống thực tế giúp con người nhận ra những mặt khuất của xã hội mà tri thức hàn lâm thường bỏ sót.", "Văn chương chỉ có ý nghĩa khi phản ánh trực tiếp hiện thực đời sống.", "Những người lao động bình dị có điều kiện tiếp xúc trực tiếp với bản chất con người."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Rượu hồng em uống cho say,</i><br><i>Vui cùng chị một vài giây cuối cùng.</i><br><i>(Rồi đây sóng gió ngang sông,</i><br><i>Đầy thuyền hận, chị lo không tới bờ)</i><br>(Lỡ bước sang ngang, Nguyễn Bính)<br>Tác dụng chính của biện pháp tu từ chêm xen là gì?", "choices": ["Tạo âm hưởng nhịp nhàng cho bài thơ,", "Tăng sức gợi hình, gợi cảm cho câu thơ", "Bổ sung dự cảm của nhân vật “em” về tương lai của chị", "Tô đậm dự cảm và nỗi đau của chị khi về nhà chồng"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng", "choices": ["Vườn hồng xum xuê hoa lá, khoe sắc thắm dưới nắng sớm.", "Cả lớp cười nắc nẽ trước trò hề của cậu bạn tinh nghịch.", "Nền nếp quân đội không dễ dàng với một người vô kỉ luật như anh.", "“Chuyện đó có gì mà giấu diếm?” - Hồng nói bằng một giọng bực dọc."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng", "choices": ["Bà cụ sống rất dè sẻn, tiết kiệm từng đồng một để dành dụm nuôi các cháu.", "Ngôi nhà cũ kĩ nằm lặng lẽ giữa những triềng đồi xanh thẳm.", "Trường học luôn yêu cầu học sinh xếp hàng theo quy cũ trước khi vào lớp.", "Em bé lạc mẹ giữa chợ, giáo giác tìm kiếm khắp nơi."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Sau khi em gái của tôi tặng con búp bê cho Đào, đứa trẻ vui sướng, mỉm cười rực rỡ.</i><br>Đây là câu ______", "choices": ["thiếu thành phần câu", "mơ hồ từ vựng", "sai về liên hệ ngữ nghĩa giữa các thành phần câu", "sai trật tự từ"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Tiếng ca vắt vẻo lưng chừng núi,</i><br><i>Hổn hển như lời của nước mây.”</i><br>(Tố Hữu)<br>Từ nào được dùng với nghĩa chuyển?", "choices": ["vắt vẻo", "núi", "tiếng ca", "lưng chừng"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "(1) Cơn gió mùa thu hạ lướt qua vùng sen trên hồ, nhuần thấm cái hương thơm của lá, như báo trước mùa về của một thức quà thanh nhã và tinh khiết. (2) Các bạn ngửi thấy, khi đi qua những cánh đồng xanh, mà hạt thóc nếp đầu tiên làm trĩu thân lúa còn tươi, ngửi thấy cái mùi thơm mát của bông lúa non không? (3) Trong cái vỏ xanh kia, một giọt sữa trắng thơm, phảng phất hương vị mùi hoa cỏ. (4) Dưới ánh nắng, giọt sữa dần dần đông lại, bông lúc càng ngày càng cong xuống, nặng vì cái chất quý trong sạch của Trời.<br>(Phỏng theo Một thức quà của lúa non: Cốm)<br>Câu ghép trong đoạn văn trên là câu nào?", "choices": ["(1)", "(2)", "(3)", "(4)"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Từ Hán Việt nào sau đây là từ ghép đẳng lập?", "choices": ["bình minh", "thất vọng", "vĩ nhân", "vinh nhục"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng", "choices": ["Mỗi buổi sáng, chị Hoà trang điểm, rửa mặt và soi gương.", "Bị bắt nạt, không phải mọi người đều có chung một phản ứng.", "Từ ngày cải tiến phương pháp giảng dạy, các em học sinh đã đạt kết quả cao.", "Những trạng thái cảm xúc dễ chịu của con người là hạnh phúc, vui sướng, bình yên, khi ăn một món ăn ngon, khi được người mình thích tỏ tình,..."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Từ “cả” trong câu nào sau đây là trợ từ?", "choices": ["Về chuyện ấy, chẳng có gì phải buồn cả!", "Chớ thấy sóng cả mà ngã tay chèo.", "Trời, cậu hoá ra lại là một người cả tin như thế!", "Anh cả thường là người phải lo cho các em nhiều nhất nhỉ?"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Những quan niệm của phái ______ về cảm giác cái tôi cá nhân đã in đậm nét trong các bài thơ Huyền diệu, Nguyệt cầm (Xuân Diệu), Đi giữa đường thơm (Huy Cận), Đồ mi họa, Sọ người (Bích Khê). Các nhà thơ mới còn tiếp thu tính nhạc điệu, cái tiên nghiệm, tinh thần âm nhạc của trường phái thơ này<br>(Trích theo Những ảnh hưởng của văn học phương Tây đối với văn học Việt Nam hiện đại, Hà Văn Lưỡng)<br>Điền từ vào chỗ trống:", "choices": ["tượng trưng", "siêu thực", "lãng mạn", "hiện thực"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Thể thơ song thất lục bát có câu song thất vần trắc xen câu lục bát vần bằng; có vần chân và vần lưng khiến cho âm điệu xoắn xuýt, thích hợp với tình cảm ai oán, thương xót của thể loại _______ hơn bất cứ thể loại nào khác.</i><br>Điền từ vào chỗ trống:", "choices": ["ngâm khúc", "hịch", "văn tế", "truyện truyền kì"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Sau nhiều lần thử nghiệm không đạt, tôi mới chiêm nghiệm lại và nhận ra “lỗ hổng” lớn nhất đó là vốn sống thực tế. Dẫu có đi nhiều, nhưng nếu chỉ “cưỡi ngựa xem hoa”, khai thác thông tin không đầy đủ, thì lấy đâu ra tư liệu hay để đắp lên trang giấy với hàng ngàn con chữ! Tôi tìm lại những bài ______ và ______ nổi tiếng từ nhà văn Vũ Trọng Phụng, Nguyễn Tuân đến nhà báo Thép Mới, Hữu Thọ mới thực sự cảm phục sự tài hoa của họ.</i>", "choices": ["truyện ngắn – phóng sự", "phóng sự – bút ký", "hồi ký – nhật ký", "tùy bút – tản văn"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đâu không phải là đặc trưng của văn học trung đại?", "choices": ["Tính quy phạm chặt chẽ", "Tính phi ngã, đề cao cộng đồng", "Tính trang nhã, ước lệ, tượng trưng", "Tính độc đáo, đề cao bản sắc cá nhân"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Khen thay con tạo khéo khôn phàm</i><br><i>Một đố giương ra biết mấy ngoàm</i><br><i>Lườn đá cỏ leo sờ rậm rạp</i><br><i>Lách khe nước rỉ mó lam nham</i><br><i>Một sư đầu trọc ngồi khua mõ</i><br><i>Hai tiểu lưng tròn đứng sau am</i><br><i>Đến mới biết là Hang Thánh Hoá</i><br><i>Chồn chân mỏi gối vẫn còn ham!</i><br>(Hang Thánh Hoá, Hồ Xuân Hương)<br>Đâu không phải là nhận định đúng về bài thơ trên?", "choices": ["Bài thơ xiển dương, ca ngợi thực hành tôn giáo ở hang Thánh Hoá.", "Thiên nhiên trong bài thơ gợi liên tưởng về cơ thể con người.", "Ngôn từ của bài thơ không tuân theo tính nhã của văn học trung đại.", "Bài thơ cho thấy sức biểu đạt đa dạng, phong phú của tiếng Việt."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b>Não trẻ em: phần cứng chưa được cài đặt</b><br>Để hiểu tại sao trẻ em đặc biệt dễ bị tổn thương, chúng ta cần nói về một trong những sự thật ít được biết đến nhất trong khoa học thần kinh phát triển: não người không hoàn thiện cho đến năm 25 tuổi.<br>Vỏ não trước trán (prefrontal cortex) - vùng não chịu trách nhiệm kiểm soát xung động, đánh giá hậu quả dài hạn, so sánh phần thưởng tức thì với chi phí lâu dài, và quan trọng nhất là khả năng tự hỏi “mình có thực sự muốn làm điều này không?” - là vùng cuối cùng trưởng thành. Ở một đứa trẻ 12 tuổi, vùng này đang trong giai đoạn tái cấu trúc quy mô lớn. Ở tuổi 15, nó vẫn chưa hoàn thiện. Ở tuổi 18 - cái tuổi mà về mặt pháp lý chúng ta gọi là “người lớn” - nó vẫn đang tiếp tục phát triển.<br>Trong khi đó, hệ thống limbic - trung tâm xử lý cảm xúc và phần thưởng, nơi dopamine được tiết ra mạnh nhất - lại hoạt động tối ưu sớm hơn đáng kể, thường vào giai đoạn đầu tuổi teen.<br>Sarah-Jayne Blakemore, nhà thần kinh học nhận thức tại UCL và sau này là Đại học Cambridge, người dẫn đầu nghiên cứu về não bộ thiếu niên trong hơn hai thập kỷ, mô tả khoảng cách này bằng một hình ảnh đáng nhớ: não tuổi thiếu niên giống như một chiếc xe có động cơ mạnh nhưng hệ thống phanh chưa được lắp đặt đầy đủ. Hệ thống tìm kiếm phần thưởng hoạt động hết công suất - nhạy cảm với dopamine hơn bất kỳ giai đoạn nào khác trong cuộc đời - trong khi hệ thống kiểm soát và điều tiết vẫn đang trong quá trình xây dựng. Mạng xã hội tấn công chính xác vào điểm mù này. Và đây không phải là ẩn dụ - đây là mô tả giải phẫu học.<br><b>Khi não phát triển trong môi trường dopamine nhân tạo</b><br>Vấn đề không chỉ là trẻ em dành quá nhiều thời gian trên mạng xã hội. Vấn đề là não bộ trẻ em - đang trong quá trình tự tổ chức lại về mặt cấu trúc - phát triển trong một môi trường dopamine nhân tạo, với cường độ và tần suất mà não người chưa từng tiến hóa để xử lý.<br>Chương trình Nghiên cứu Phát triển Não bộ và Nhận thức Thiếu niên (the ABCD Study) - nghiên cứu chiều dọc lớn nhất về não bộ thiếu niên ở Mỹ với gần 12.000 trẻ em được theo dõi từ năm 9-10 tuổi - đã cung cấp những bằng chứng có thể đo lường được. Các phân tích từ nhóm nghiên cứu của Paulus, Squeglia, Bagot và cộng sự cho thấy trẻ dành nhiều thời gian đáng kể trên mạng xã hội có sự khác biệt trong cấu trúc não và hoạt động của vỏ não trước trán, theo hướng tăng nhạy cảm với các tín hiệu xã hội và giảm khả năng điều tiết cảm xúc.<br>Nói đơn giản hơn: não bộ đang học cách vận hành trong một môi trường mà sự chấp thuận xã hội đến ngay lập tức, liên tục, và có thể đo lường bằng con số. Khi môi trường đó trở thành môi trường phát triển chính của não, não sẽ được tối ưu hóa cho môi trường đó - dù nó không phải là thế giới thật.<br><i>“Não của trẻ em không chỉ đang tiếp nhận kích thích từ môi trường - nó đang dùng những kích thích đó làm nguyên liệu để tự xây dựng.” - </i>TS Hảo Quang<br>Người lớn đọc đến đây có thể nghĩ: bản thân tôi cũng bị cuốn vào mạng xã hội, nhưng tôi vẫn ổn. Điều đó chứng tỏ gì?<br>Nó chứng tỏ rằng mạng xã hội ảnh hưởng đến tất cả mọi người - nhưng không ảnh hưởng theo cùng một cách với não đã trưởng thành và não đang phát triển. Khi một người trưởng thành sử dụng mạng xã hội nhiều, họ đang đối mặt với một hệ thống được thiết kế để khai thác những điểm yếu tâm lý phổ quát của loài người. Nhưng về cơ bản, họ đang đấu tranh với một thói quen được hình thành trên nền của một cấu trúc não đã hoàn thiện.<br>Khi một đứa trẻ 12 tuổi làm điều tương tự, điều đang xảy ra là khác về bản chất. Não của trẻ em không chỉ đang tiếp nhận kích thích từ môi trường - nó đang dùng những kích thích đó làm nguyên liệu để tự xây dựng. Các kết nối thần kinh đang được hình thành. Các mạch não đang được củng cố hoặc loại bỏ theo nguyên lý “dùng hay bỏ”. Những gì não trẻ em tiếp xúc nhiều nhất trong giai đoạn này sẽ định hình - theo nghĩa đen, về mặt vật lý - cấu trúc cơ bản não cho đến hết cuộc đời.<br>(Trích Lướt mạng xã hội gây tác hại cho não trẻ em ngang với thuốc lá, Hảo Quang)", "cauHoi": [{"question": "Theo văn bản, đặc điểm nào của não bộ trẻ em được nhấn mạnh?", "choices": ["Não đã hoàn thiện từ cuối tuổi thiếu niên.", "Não còn đang phát triển và tái cấu trúc mạnh mẽ.", "Não hoạt động ổn định hơn người trưởng thành.", "Não ít chịu ảnh hưởng từ môi trường bên ngoài."], "correctIndex": 1, "explain": ""}, {"question": "Việc so sánh não thiếu niên với “chiếc xe có động cơ mạnh nhưng hệ thống phanh chưa được lắp đặt đầy đủ” chủ yếu nhằm làm rõ điều gì?", "choices": ["Sự phát triển nhanh của khả năng phản ứng cảm xúc.", "Tính phức tạp trong hoạt động của hệ thần kinh.", "Sự mất cân bằng giữa hệ thưởng và hệ kiểm soát.", "Tác động trực tiếp của mạng xã hội lên hành vi."], "correctIndex": 2, "explain": ""}, {"question": "Đâu là thông tin không đúng dựa trên nội dung văn bản?", "choices": ["Não người lớn không bị ảnh hưởng khi nghiện mạng xã hội vì đã phát triển hoàn thiện.", "Mạng xã hội có ảnh hưởng trực tiếp đến hệ thống điều tiết và kiểm soát dopamine của trẻ.", "Có những bằng chứng khoa học khách quan cho thấy ảnh hưởng của mạng xã hội lên trẻ em.", "Ở tuổi 18, vùng não trước vẫn tiếp tục phát triển."], "correctIndex": 0, "explain": ""}, {"question": "Thông tin chính của văn bản trên là gì?", "choices": ["Quá trình phát triển của các vùng não ở con người từ nhỏ đến trưởng thành", "Sự khác biệt trong cấu trúc não giữa trẻ em và người lớn", "Ảnh hưởng của môi trường, đặc biệt là mạng xã hội, đến sự phát triển não trẻ em", "Vai trò của dopamine trong hoạt động của hệ thần kinh"], "correctIndex": 2, "explain": ""}, {"question": "Thông điệp phù hợp nhất rút ra từ văn bản là gì?", "choices": ["Não bộ con người phụ thuộc hoàn toàn vào yếu tố sinh học.", "Mạng xã hội chỉ thực sự nguy hiểm với trẻ dưới 12 tuổi.", "Môi trường số có thể để lại ảnh hưởng lâu dài lên não trẻ em.", "Người trưởng thành hầu như không bị tác động bởi mạng xã hội."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<i>Trong thời đại toàn cầu hóa, người ta đang nói đến hội nhập văn hóa, đến văn học thế giới; vậy mà nay nói chuyện văn học địa phương thì xem chừng như hơi bị lạc hậu, cổ lỗ chăng? Thế nhưng nghĩ kỹ thì thấy có những giá trị văn học toàn nhân loại lại xuất phát từ cái nôi của một vùng đất, một quê hương bé nhỏ. Trăm năm cô đơn của Gabriel Garcia Marquez tái hiện làng Macondo hẻo lánh như một sản phẩm hư cấu nghệ thuật được xây dựng từ chất liệu làng quê Atacarata của tác giả. Tuổi thơ của Pablo Neruda gắn liền với những cánh đồng và những khu rừng ở Temulco, miền cực nam Chi-lê và ông nói: “Temulco là cái phong cảnh của tôi, là nét chính yếu của thơ tôi”. Còn Quê hương tan rã của Chinua Achebe thì được khơi nguồn cảm hứng từ làng Ogidi ở vùng hạ lưu sông Niger, nơi bộ lạc Ibo sinh sống, cũng là nơi nhà văn chào đời.</i><br><i>Nước Việt Nam của chúng ta là một dải đất hẹp kéo dài từ “từ ải Nam Quan đến mũi Cà Mau”, từ Trà Cổ rừng dương đến Cà Mau rừng đước (Tố Hữu). Tình cảm thống nhất đất nước không bao giờ phai nhạt, trong trái tim người đi trên con đường thiên lý vẫn mang theo tâm tình từ miền Bắc: “Tôi theo người vượt quan san, vẽ lối mòn gìn giữ quê hương ngăn đường giặc Hán”, như Phạm Duy viết trong trường ca Con đường cái quan.</i><br><i>Nhưng tính thống nhất đó không xóa nhòa hay bào mòn tính đa dạng của văn hóa vùng miền. Trong văn học, tác phẩm của Sơn Nam, Bình Nguyên Lộc, Đoàn Giỏi... ở miền Nam khác với tác phẩm của Võ Hồng, Quách Tấn, Nguyễn Văn Xuân... ở miền Trung; với tác phẩm của Nguyễn Tuân, Tô Hoài, Bùi Ngọc Tấn... ở miền Bắc không chỉ về nội dung thể hiện mà cả về phong cách kể chuyện, ngôn ngữ và giọng điệu. Họ làm nên một tài sản tinh thần vô giá của nhân dân. Nhân dân tự hào về giới trí thức sáng tạo của mình, những người cũng biết chăm vườn tưới cây, cũng ăn bắp ngô và khoai lang, nhưng biết cách nói lên nỗi đau và niềm thao thức của đồng bào chung quanh đang sống trong tình cảnh vất vả và lắm khi bất hạnh.</i><br><i>Để được vậy, những tài năng đó cần có những khoảng không gian rộng lớn cho sáng tạo, cần được thấu hiểu và lắng nghe trong cái môi trường văn hóa nhiều khi chật hẹp của họ. Mặt khác, bản thân họ cũng phải tự mình vượt qua những rào cản về tâm lý, nhất là tâm lý tỉnh lẻ, để từ chỗ đứng của mình mà suy tưởng và tái hiện về những vấn đề lớn lao của đất nước và con người. Để mượn cách nói của Miguel Torga, nhà văn Bồ Đào Nha, văn học thế giới chính là văn học địa phương không có những bức tường.</i><br><i>Đọc Chiếc cầu trên sông Drina của Ivo Andritch qua bản dịch của Nguyễn Hiến Lê, tôi khâm phục tài năng của nhà văn, qua câu chuyện và số phận của một cây cầu, đã tái hiện bao nhiêu chuyện về nhân tình thế thái và số phận con người ở đất nước Nam Tư những năm tháng đã xa. Tôi từng mơ ước có một Ivo Andritch của Việt Nam. Đất nước ta từ Bắc vô Nam cũng có vô số những cây cầu bắc qua những dòng sông, kênh rạch, mà cây cầu nổi tiếng nhất có tên là Hiền Lương bắc qua sông Bến Hải. Nơi đó đã trở thành vết cắt, vết thương của dân tộc. Nhiều nhà văn, nhà thơ đã đưa cầu Hiền Lương và sông Bến Hải vào tác phẩm, như hình ảnh của một chiến tuyến. Nguyễn Tuân viết rất hay về “sông tuyến”, nhưng nhà văn vẫn không đứng cao hơn môi trường chính trị của ông, chỉ thấy khát vọng của dân tộc mà chưa nhìn thấu những vết thương sâu hoáy trong lòng người kinh qua một cuộc chiến tranh khủng khiếp.</i><br>(Huỳnh Như Phương)", "cauHoi": [{"question": "Theo văn bản, yếu tố nào <b>KHÔNG</b> được nêu như một biểu hiện của sự đa dạng văn học vùng miền Việt Nam?", "choices": ["Hệ thống thể loại văn học", "Nội dung phản ánh đời sống", "Phong cách kể chuyện", "Ngôn ngữ và giọng điệu"], "correctIndex": 0, "explain": ""}, {"question": "Việc tác giả dẫn các ví dụ về Gabriel García Márquez, Pablo Neruda và Chinua Achebe chủ yếu nhằm mục đích gì?", "choices": ["Chứng minh văn học địa phương mang tính hạn chế, cục bộ", "Khẳng định văn học thế giới thường mang tính hư cấu", "Làm rõ mối quan hệ giữa cội nguồn địa phương và giá trị toàn cầu", "So sánh văn học Việt Nam với văn học nước ngoài"], "correctIndex": 2, "explain": ""}, {"question": "Nhận định nào sau đây phù hợp nhất với quan điểm của tác giả về mối quan hệ giữa tính thống nhất và tính đa dạng trong văn học Việt Nam?", "choices": ["Tính thống nhất làm suy giảm bản sắc vùng miền", "Tính đa dạng phủ nhận hoàn toàn tính thống nhất", "Tính thống nhất và đa dạng cùng tồn tại và bổ sung cho nhau", "Tính đa dạng chỉ tồn tại trong văn học hiện đại"], "correctIndex": 2, "explain": ""}, {"question": "Ý kiến về Nguyễn Tuân trong đoạn văn cho thấy điều gì về giới hạn của nhà văn?", "choices": ["Nhà văn không quan tâm đến chính trị", "Nhà văn luôn phản ánh đầy đủ hiện thực xã hội", "Nhà văn có thể bị chi phối bởi bối cảnh tư tưởng và thời đại", "Nhà văn không thể viết về chiến tranh"], "correctIndex": 2, "explain": ""}, {"question": "Đâu là cách hiểu phù hợp về câu: “Văn học thế giới chính là văn học địa phương không có những bức tường.”", "choices": ["Văn học địa phương cần vượt lên trên tính hạn hẹp vùng miền để trở thành văn học kinh điển của nhân loại.", "Văn học địa phương giàu bản sắc, khi đạt tới chiều sâu, có thể phản ánh những giá trị chung của nhân loại.", "Văn học thế giới là tập hợp của các nền văn học địa phương riêng biệt, không có sự liên hệ với nhau.", "Văn học chỉ trở thành văn học thế giới khi không còn mang dấu ấn địa phương."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}], "anh": [{"noiDungChung": null, "cauHoi": [{"question": "<i class=\"huong-dan-cau\">Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i><br>She had made Helen a dress which showed _____ her tiny waist.", "choices": ["up", "over", "off", "through"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "The children _____ their homework when I got home.", "choices": ["were doing", "were done", "did", "are doing"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "No matter how much seasoning you add, this soup will never taste _____ it<br>did when my grandmother made it.", "choices": ["as good as", "as well as", "worse than", "better than"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "The calming effect seemed _____ for about ten minutes.", "choices": ["lasting", "to last", "last", "to lasting"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "There is _____ doubt that a diet high in fiber is more satisfying.", "choices": ["several", "many", "few", "little"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 36-40: Each of the following sentences has one error (A, B, C, or D). Find it and blacken your choice on your answer sheet.</i></b>", "cauHoi": [{"question": "This <u>has</u> covered <u>the</u> range of exotic <u>beasts</u> from Kentucky Derby winners and farm animals <u>through</u> to pandas and white tigers.", "choices": ["has", "the", "beats", "through"], "correctIndex": 1, "explain": ""}, {"question": "<u>A</u> lot of <u>sugar</u> in the supermarket <u>are</u> sold because people use <u>it</u> daily.", "choices": ["A", "sugar", "are", "it"], "correctIndex": 2, "explain": ""}, {"question": "In her panic <u>she</u> couldn&#x27;t remember <u>who</u> <u>was</u> <u>Mr</u>. <u>Grainger&#x27;s</u> cabin.", "choices": ["she", "who", "was", "Mr Grainger&#x27;s"], "correctIndex": 1, "explain": ""}, {"question": "Hopefully the findings <u>of</u> this report will help <u>remind</u> people that <u>his</u> actions<br>on the road do have an impact on <u>other</u> drivers.", "choices": ["of", "remind", "his", "other"], "correctIndex": 2, "explain": ""}, {"question": "<u>The</u> manager was <u>impressed</u> by the creativity and attention <u>to</u> detail shown in<br><u>Sarah</u> report.", "choices": ["The", "impressed", "to", "Sarah"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: </b>Which of the following best restates each of the given sentences?", "cauHoi": [{"question": "“Why don’t you visit your grandparents this weekend?” said Sarah.", "choices": ["Sarah suggested that I should visit my grandparents that weekend.", "Sarah told me not to visit my grandparents that weekend.", "Sarah warned me to visit my grandparents that weekend.", "Sarah asked me not to visit my grandparents that weekend."], "correctIndex": 0, "explain": ""}, {"question": "The game was postponed because it started raining heavily.", "choices": ["The game would be postponed unless it started raining heavily.", "If it hadn’t rained heavily, the game wouldn’t have been postponed.", "If it rains heavily, the game will not be postponed.", "If it rained heavily, the game would not be postponed."], "correctIndex": 1, "explain": ""}, {"question": "No one in the team plays chess better than Alex.", "choices": ["Alex doesn’t play chess better than anyone in the team.", "Alex is the best chess player in the team.", "Everyone plays chess better than Alex in the team.", "Alex plays chess as well as everyone in the team."], "correctIndex": 1, "explain": ""}, {"question": "It is advisable for you to take this class before registering for the exam.", "choices": ["It’s not a good idea to take this class before registering for the exam.", "You must take this class before registering for the exam.", "You should have taken this class before registering for the exam.", "You should take this class before registering for the exam."], "correctIndex": 3, "explain": ""}, {"question": "The park is quieter now, perhaps because of the colder weather.", "choices": ["The decline in the park’s visitors is unlikely due to colder weather.", "Cold weather may be the reason for the decline in the park’s visitors.", "The park’s decline in visitors is certainly due to colder weather.", "It is possible that colder weather will not affect the park’s visitors."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question.</i></b><br><b>1.</b> Buying the week’s groceries is not what they call shopping therapy. You want to get it over and done with quickly, so you head for the nearest supermarket, you find everything you need under one roof, and you feel glad that those days of going in and out of different shops in the high street are over, and that terrible music they play doesn’t even bother you any longer. Supermarkets seem to be a big plus. There is a downside, though.<br><b>2.</b> In the UK 90% of all the food people consume is bought at 5 different supermarket chains. This makes these companies extremely powerful, especially when it comes to determining the terms of contracts with the smaller companies that supply them. Supermarkets use their huge buying power to squeeze suppliers to get the best deal. Milk is a good example. Supermarkets like to use things like milk and bread, which are at the top of almost everyone’s shopping list, to attract customers. To offer the lowest price possible to the consumer, the supermarkets force dairy farmers to sell milk at less than the cost of production. On average, most UK dairy farms operate at a loss and can only survive with the help of subsidies. Supermarkets keep their profit margin while farmers are left struggling to make ends meet, and the taxpayer unknowingly pays to support the system.<br><b>3.</b> It would be nice if local grocers supported local agriculture. But for the big supermarkets this<br>just doesn’t make sense. You don’t want little farmers thinking they can dictate prices. So supermarkets have started a global search for the cheapest possible agricultural produce. In many supermarkets it is difficult to find anything which is produced locally. The consumer might just be happy to get a reasonably priced meal, but we should also bear in mind the impact on local producers, local retailers and the environment (transporting all that produce around the world does<br>nothing to limit the production of greenhouse gases).<br><b>4.</b> There is also the Câumark over the quality of the supposedly fresh food sold by supermarkets. To store produce so that it can be sold at a higher price out of season or to keep it “fresh” while it is being transported across entire continents, suppliers inevitably use preservatives to inhibit the natural rotting process.<br><b>5.</b> Because the biggest and newest supermarkets are big outside town centers where land is cheaper and it is easier to build the adjacent car park, the rise of the supermarket has helped to worsen the situation of the British town center. Judging by the number of shops that have closed in English town centers you would think that the economy has hit an all-time low. It hasn’t. It’s just that the shopping has moved out of town. What’s left behind is, quite frankly, ugly. Anyone who dispassionately weighed up the pros and cons of supermarkets would quickly come to the conclusion that drastic measures need to be taken. Perhaps even demolition. But this is unlikely to come about. The modern world is all about shopping, and the freedom to buy whatever you want, so it would be outrageous for our political leaders to try to stop people shopping at some particular kind of shop, and without the political will to change public opinion people will just carry on shopping wherever it is most convenient for them, even if jobs are lost, agriculture and local producers suffer, sea levels rise and the health of the nation deteriorates. Who cares about all that anyway when there is a free car park and so many special offers?<br><b><i>Choose an option (A, B, C, or D) that best answers each question.</i></b>", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["The benefits of shopping therapy", "The impact of communities and agriculture on local farmers and town centers", "The negative effects of supermarkets on local farmers and town centers", "The rise of supermarket chains and their global influence"], "correctIndex": 2, "explain": ""}, {"question": "What does the word “them” refer to in paragraph 2?", "choices": ["The smaller companies", "The supermarket chains", "The people who consume food", "The contracts"], "correctIndex": 1, "explain": ""}, {"question": "In paragraph 3, which of the following is NOT mentioned?", "choices": ["Locally produced products are difficult to find in many supermarkets.", "Transporting agricultural products globally harms the environment.", "Supermarkets search for the cheapest agricultural products globally.", "Supermarkets support local farmers&#x27; pricing decisions."], "correctIndex": 3, "explain": ""}, {"question": "The closest meaning to the word “inevitably” in paragraph 4 is _____.", "choices": ["Certainly", "Accidentally", "Willingly", "Occasionally"], "correctIndex": 0, "explain": ""}, {"question": "What are stated details in the reading text in paragraph 4?", "choices": ["Supermarkets offer fresh food that is naturally grown without preservatives.", "Supermarkets only sell locally produced food.", "Supermarkets sell only seasonal produce.", "Preservatives are used to maintain the freshness of food during transport."], "correctIndex": 3, "explain": ""}, {"question": "What can be inferred about the impact of supermarkets on British town centers in paragraph 5?", "choices": ["Supermarkets have improved the appearance of British town centers.", "Supermarkets have contributed to the decline of town center businesses.", "Supermarkets have had no impact on the British economy.", "Supermarkets have created more job opportunities in town centers."], "correctIndex": 1, "explain": ""}, {"question": "What are stated details in the reading text in paragraph 5?", "choices": ["Town centers are thriving due to the success of local supermarkets.", "Supermarkets have not contributed to the closure of local businesses.", "The growth of supermarkets outside town centers has led to the closure of shops in town centers.", "Supermarkets are closing due to their lack of parking spaces."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: <b>Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.</b><br><b>1.</b> Social networks connect people at low cost; this can be beneficial for entrepreneurs and small<br>businesses looking to expand their contact base. These networks often act as a customer relationship management tool for companies selling products and services. Companies can also use social networks for advertising in the form of banners and text ads. Since businesses operate globally, social networks can make it easier to keep in touch with contacts around the world.<br><b>2.</b> Social networks are beginning to be adopted by healthcare professionals as a means to manage institutional knowledge, disseminate peer-to-peer knowledge, and to highlight individual physicians and institutions. The advantage of using a dedicated medical social networking site is<br>that all the members are screened against the state licensing board&#x27;s list of practitioners. The role of social networks is especially of interest to pharmaceutical companies who spend approximately &quot;32 percent of their marketing dollars&quot; attempting to influence the opinion leaders of social networks.<br><b>3.</b> Various social networking sites have sprung up catering to different languages and countries.<br>The popular site Facebook has been cloned for various countries and languages and some<br>specializing in connecting students and faculty.<br><b>4.</b> Several websites are beginning to tap into the power of the social networking model for social<br>good. Such models may be highly successful in connecting otherwise fragmented industries and<br>small organizations without the resources to reach a broader audience with interested and<br>passionate users. Users benefit by interacting with a like-minded community and finding a channel<br>for their energy and giving.<br><b>5.</b> Few social networks currently charge money for membership. In part, this may be because<br>social networking is a relatively new service, and the value of using it has not been firmly<br>established in customers&#x27; minds. Companies such as MySpace and Facebook sell online advertising on their site. Hence, they are seeking large memberships, and charging for membership would be counterproductive. Some believe that the deeper information that the sites have on each user will allow much better-targeted advertising than any other site can currently provide. Sites are also seeking other ways to make money, such as by creating an online marketplace or by selling<br>professional information and social connections to businesses.<br><b>6.</b> On large social networking services, there have been growing concerns about users giving out too much personal information and the threat of sexual predators. Users of these services need to be aware of data theft or viruses. However, large services, such as MySpace, often work with law enforcement to try to prevent such incidents. In addition, there is a perceived privacy threat in relation to placing too much personal information in the hands of large corporations or governmental bodies, allowing a profile to be produced on an individual&#x27;s behavior on which decisions, detrimental to an individual, may be taken.<br><b>7.</b> Social network services are increasingly being used in legal and criminal investigations. Information posted on sites such as MySpace and Facebook, has been used by police, probation, and university officials to prosecute users of said sites. In some situations, content posted on MySpace has been used in court.<br><i>Choose an option (A, B, C, or D) that best answers each question.</i>", "cauHoi": [{"question": "The best title of the passage can be _____.", "choices": ["The Advertisement of Business on Social Networks", "The Dangers of Overusing Social Networking", "How Social Networks Are Changing Business Practices", "The Negative Aspects of Social Networking"], "correctIndex": 2, "explain": ""}, {"question": "In paragraph 2, which of the following can be inferred about pharmaceutical companies?", "choices": ["They spend a small amount of money on social networking.", "They use social networks to connect with healthcare professionals.", "They are not interested in social networks for marketing.", "They use social networks to build hospitals."], "correctIndex": 1, "explain": ""}, {"question": "It can be seen in paragraphs 1 and 2 that _____.", "choices": ["Social networks are only used for marketing and advertising", "Social networks can benefit businesses and healthcare professionals", "Social networks create privacy risks for users", "Social networks are a new phenomenon with no clear purpose"], "correctIndex": 1, "explain": ""}, {"question": "In paragraph 3, the author uses the word &quot;cloned&quot; in order to _____.", "choices": ["Show that social networking sites are unique to each country", "Suggest that social networking sites can be copyrighted", "Discuss how different sites offer different services", "Illustrate how Facebook has been replicated in different places"], "correctIndex": 3, "explain": ""}, {"question": "It can be inferred from paragraph 4 that _____.", "choices": ["Social networks are mainly focused on entertainment, not business", "Users find it difficult to interact with like-minded communities", "Social networks create division in industries", "Social networking can be used for both personal and charitable purposes"], "correctIndex": 3, "explain": ""}, {"question": "The phrase &quot;social networking model&quot; in paragraph 4 refers to _____.", "choices": ["A system where people are connected through virtual communication", "A platform used for legal investigations", "A business model focused on subscription fees", "A structure to connect educational institutions"], "correctIndex": 0, "explain": ""}, {"question": "The word &quot;counterproductive&quot; in paragraph 5 can be replaced by _____.", "choices": ["Profound", "Beneficial", "Inefficient", "Spiritual"], "correctIndex": 2, "explain": ""}, {"question": "In paragraph 6, it is NOT mentioned that _____.", "choices": ["Large social networking services work with law enforcement", "Personal information on social networks may be misused", "Users of social networks face security risks", "Social networks are sometimes used for illegal activities"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Khi các phản ứng hóa học xảy ra thường có sự trao đồi nhiệt với môi trường làm thay đổi nhiệt độ môi trường. Dựa vào nhiệt phản ứng có thể chia thành hai loại: Phản ứng tỏa nhiệt là phản ứng giải phóng năng lượng dưới dạng nhiệt; Phản ứng thu nhiệt là phản ứng hấp thụ năng lượng dưới dạng nhiệt.<br>Biến thiên enthalpy chuẩn của một phản ứng hóa học, kí hiệu là <span class=\"ct\">Δ<sub>r</sub>H<sub>298</sub>°</span>, chính là lượng nhiệt (tỏa ra hoặc thu vào) của phản ứng đó ở điều kiện chuẩn. Điều kiện chuẩn là điều kiện ứng với áp suất 1 bar (đối với chất khí), nồng độ <span class=\"ct\">1molL<sup>−1</sup></span> (đổi với chất tan trong dung dịch) và nhiệt độ thường được chọn là <span class=\"ct\">298K(25°C)</span>.<br>Phản ứng tổng quát: <span class=\"ct\">aA + bB → cC + dD</span><br>Biểu thức xác định biến thiên enthalpy chuẩn của phản ứng được xác định:<br>\\[\\Delta_{r}H_{298}^{o} = c\\Delta_{f}H_{298}^{o}(C) + \\ \\ d\\Delta_{f}H_{298}^{o}(D) - \\ a\\Delta_{f}H_{298}^{o}(A) - \\ \\ b\\Delta_{f}H_{298}^{o}(B)\\]<br>Trong đó <span class=\"ct\">Δ<sub>f</sub>H<sub>298</sub>°</span> của một chất là nhiệt tạo thành 1 mol chất đó từ các đơn chất tương ứng ở điều kiện chuẩn. (Nhiệt tạo thành chuẩn của đơn chất bằng 0 ).", "cauHoi": [{"question": "Cho các phản ứng hóa học sau, có bao nhiêu quá trình thu nhiệt?<br>(a) Đốt cháy khí gas.<br>(b) Nung đá vôi.<br>(c) Sự tiêu hóa thức ăn.<br>(d) Đá viên tan chảy", "choices": ["1", "2", "3", "4"], "correctIndex": 2, "explain": "<b>⬥ Đáp án: C (b, c, d)</b>"}, {"question": "Tính lượng nhiệt sinh ra khi đốt cháy hoàn toàn 7,8 gam <span class=\"ct\">C<sub>6</sub>H<sub>6</sub></span> (l). Biết khối lượng phân tử của C<sub>6</sub>H<sub>6</sub> là 78 g/mol. Cho enthalpy tạo thành chuẩn của các chất tương ứng:<br><table class=\"bang-de\"><tr><td>Chất</td><td>\\[C_{6}H_{6}(l)\\]</td><td>\\[CO_{2}(g)\\]</td><td>\\[H_{2}O(g)\\]</td></tr><tr><td>\\[\\Delta_{f}H_{298}^{0}(kJ/mol)\\]</td><td>+49</td><td>\\[- 393,5\\]</td><td>\\[- 241,82\\]</td></tr></table>", "choices": ["<span class=\"ct\">3135,46 kJ</span>;", "<span class=\"ct\">684,32 kJ</span>;", "<span class=\"ct\">313,546 kJ</span>;", "<span class=\"ct\">68,432 kJ</span>."], "correctIndex": 2, "explain": "<b>⬥ Hướng dẫn giải: </b>C<sub>6</sub>H<sub>6</sub> + 15/2 O<sub>2</sub> <span class=\"ct\">→</span> 6CO<sub>2</sub> + 3H<sub>2</sub>O<br>Enthalpy khi đốt cháy 1 mol C<sub>6</sub>H<sub>6</sub> là<br><span class=\"ct\">Δ<sub>r</sub>H<sub>298</sub>°</span> = 6.(-393,5) + 3.(-241,82) – (49) – (0.15/2) = -3135,46 kJ<br>nC<sub>6</sub>H<sub>6</sub> = m/M = 7,8/78 = 0,1 mol<br>Khi đốt 1 mol C<sub>6</sub>H<sub>6</sub>, nhiệt tỏa ra 3135,46 kJ. Vậy khi đốt 0,1 mol C<sub>6</sub>H<sub>6</sub>, nhiệt tỏa ra 313,546 kJ <span class=\"ct\">⇒</span> <b>Đáp án C</b>"}, {"question": "Lactic acid (hay acid sữa) là hợp chất hóa học đóng vai trò quan trọng trong nhiều quá trình sinh hóa. Khi vận động mạnh cơ thể không đủ cung cấp oxygen, thì cơ thể sẽ chuyển hóa glucose thành lactic acid từ các tế bào để cung cấp năng lượng cho cơ thể (chất này gây mỏi cơ) theo phương trình<br>\\[5C_{6}H_{12}O_{6}(aq) \\rightarrow 2C_{3}H_{6}O_{3}(aq)\\ ;\\ \\Delta_{r}H_{298}^{0} = - 150kJ\\]<br>Biết rằng cơ thể chỉ cung cấp <span class=\"ct\">98%</span> năng lượng nhờ oxygen, năng lượng còn lại nhờ vào sự chuyển hóa glucose thành lactic acid. Giả sừ một người chạy bộ trong một thời gian tiêu tốn 300 kcal. Tính khối lượng lactic acid tạo ra từ quá trình chuyển hóa đó <span class=\"ct\">(1cal = 4,184J)</span>. Biết khối lượng phân tử C<sub>3</sub>H<sub>6</sub>O<sub>3</sub> là 90 g/mol.", "choices": ["30,12 gam", "9,41 gam", "16,88 gam", "35,18 gam"], "correctIndex": 0, "explain": "<b>Hướng dẫn giải: </b>Năng lượng của sự chuyển hoá glucose thành lactic acid trong quá trình chạy bộ: 2% . 300 kcal = 6 kcal = 6 000 cal ⟺ 25 104 J = 25,104 kJ.<br>Từ phương trình phản ứng: C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> → 2C<sub>3</sub>H<sub>6</sub>O<sub>3</sub> ; Δ<sub>r</sub>H<sup>0</sup><sub>298</sub>=−150kJ<br>Cứ 1 mol C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>, tỏa ra nhiệt lượng 150 kJ<br>Với 25,104 kJ, cần: 25,104.1/150 = 0,16736 mol C<sub>6</sub>H<sub>12</sub>O<sub>6</sub><br>nC<sub>3</sub>H<sub>6</sub>O<sub>3</sub> = 0,16736 . 2 = 0,33472 mol<br>Khối lượng lactic acid được tạo ra trong quá trình chuyển hoá:<br>0,334.90 = 30,1248 g. <span class=\"ct\">⇒</span> <b>Đáp án: A</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Hệ thống <b>phanh tái sinh</b> (Regenerative Braking System – RBS) là công nghệ quan trọng trên các phương tiện chạy điện như VinFast VF8, xe buýt điện và xe đạp điện. Công nghệ này cho phép chuyển đổi một phần động năng của xe khi phanh thành điện năng để nạp lại vào pin, góp phần nâng cao hiệu suất sử dụng năng lượng.<br>Khi xe đang chuyển động, động cơ điện nhận năng lượng từ pin để tạo mô-men xoắn làm quay bánh xe. Khi người lái đạp phanh, động cơ hoạt động ngược lại như một máy phát điện, biến đổi động năng (\\(K=\\dfrac{1}{2}mv^2\\)) của xe thành điện năng. Đồng thời, quá trình này tạo ra mô-men hãm giúp xe giảm tốc.Trong thực tế, không phải toàn bộ năng lượng này đều được thu hồi; một phần bị hao phí dưới dạng nhiệt. Hiệu suất thu hồi năng lượng phụ thuộc vào thiết kế hệ thống và điều kiện vận hành.", "cauHoi": [{"question": "Chức năng chính của hệ thống phanh tái sinh là:", "choices": ["Tạo ra moment xoắn để tăng tốc cho xe, tiết kiệm năng lượng", "Giảm tiêu hao nhiên liệu bằng cách thu hồi năng lượng", "Chuyển động một phần động năng để làm mát động cơ", "Thu hồi năng lượng để tăng ma sát phanh."], "correctIndex": 1, "explain": "<b>Đáp án câu 106. Chọn B.</b> vì thu một phần động năng để nạp lại vào pin, với mục đích giảm tiêu hao năng lượng.<br>Câu A sai vì tạo ra mô-men hãm không phải tạo ra moment xoắn để tăng tốc<br>Câu C sai vì chuyển động một phần động năng để nạp lại vào pin<br>Câu D sai vì thu hồi năng lượng để nạp lại vào pin"}, {"question": "Phanh tái sinh không thể thu hồi toàn bộ năng lượng vì:", "choices": ["Dung lượng pin của xe quá nhỏ nên không thể chứa hết năng lượng thu hồi", "Trong hệ thống tồn tại các tổn hao như nhiệt, điện trở và hiệu suất chuyển đổi bé hơn 1.", "Xe giảm tốc với vận tốc nhỏ nên không sinh ra đủ năng lượng", "Khi phanh thì không có dòng điện chạy trong mạch điện"], "correctIndex": 1, "explain": "<b>Đáp án câu 107. Chọn B.</b> quá trình chuyển đổi năng lượng không thể đạt hiệu suất 100%. Luôn tồn tại các tổn hao như:<br>Hao phí dưới dạng nhiệt do điện trở trong mạch<br>Ma sát cơ học ở các bộ phận truyền động<br>Hiệu suất giới hạn của động cơ khi hoạt động như máy phát<br>Vì vậy, chỉ một phần động năng của xe được chuyển thành điện năng để nạp lại pin, phần còn lại bị tiêu tán.<br><b>Câu 108.</b> Xét một xe điện VinFast VF 8 có khối lượng <span class=\"ct\">m = 2650 kg</span> và dung lượng pin <span class=\"ct\">88,72 (kWh)</span>. Khi xe giảm tốc từ <span class=\"ct\">40 (km/h)</span> xuống 0 trong thời gian <span class=\"ct\">5 (s)</span>, hệ thống phanh tái sinh tạo ra suất điện động trung bình <span class=\"ct\">E = 166,5 (V)</span> và dòng điện trung bình <span class=\"ct\">I = 40 (A)</span>. Hiệu suất chuyển đổi năng lượng để nạp lại vào pin đạt <span class=\"ct\">η = 70%</span>. Biết công suất điện sinh ra được xác định theo công thức: <span class=\"ct\">P = U·I</span>"}, {"question": "Hỏi <b>điện năng thực tế nạp vào pin</b> là bao nhiêu? (tính theo kJ)", "choices": ["<span class=\"ct\">81,7 (kJ)</span>", "<span class=\"ct\">163,3 (kJ)</span>.", "<span class=\"ct\">114,3 (kJ)</span>.", "<span class=\"ct\">228,6 (kJ)</span>"], "correctIndex": 2, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án câu 108. Chọn C</b><br>Đổi đơn vị: <span class=\"ct\">v = 40 (km/h) = 11,1 (m/s)</span><br>Động năng ban đầu: \\(K = \\dfrac{1}{2}mv^2 = \\dfrac{1}{2} \\cdot 2650 \\cdot (11{,}1)^2 \\approx 163{,}3 (\\text{kJ})\\)<br>Điện năng thu hồi: <span class=\"ct\">W = ηK = 0,7·163,3 ≈ 114,3 (kJ)</span>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Phản ứng được enzyme xúc tác là rất đặc hiệu, mỗi enzyme có thể nhận biết cơ chất đặc hiệu của nó thậm chí trong số các hợp chất có liên quan mật thiết như chất đồng phân.<br>Chất phản ứng mà enzyme tác động đến được gọi là cơ chất của enzyme. Enzyme liên kết với cơ chất (hoặc các cơ chất khi có hai hay nhiều chất phản ứng) tạo nên một phức hệ enzyme – cơ chất. Trong khi enzyme và cơ chất kết hợp, hoạt động xúc tác của enzyme biến cơ chất thành sản phẩm (hoặc các sản phẩm) của phản ứng. Một ví dụ về quá trình này có thể tóm tắt như sau:<br>Cơ chế tác động của enzyme<br>Chỉ một vùng hạn chế của phân tử enzyme liên kết thực sự với cơ chất. Vùng này được<br>gọi là trung tâm hoạt động (vùng hoạt động), điển hình là cái túi hay hố lõm trên bề mặt<br>của protein trong đó xảy ra sự xúc tác của enzyme. Thông thường, trung tâm hoạt động<br>được hình thành chỉ nhờ một số amino acid của enzyme, còn phần còn lại của phân tử<br>protein quy định khung để xác định cấu hình của vị trí hoạt động.", "cauHoi": [{"question": "Cơ chất liên kết với enzyme thông qua vùng cấu trúc không gian được gọi là", "choices": ["trung tâm điều hành.", "trung tâm vận chuyển.", "trung tâm xúc tác.", "trung tâm hoạt động."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án câu 109: Chọn D. trung tâm hoạt động.</b><br><b><u>Giải thích:</u></b> Theo đoạn thông tin: “...Chỉ một vùng hạn chế của phân tử enzyme liên kết thực sự với cơ chất. Vùng này được gọi là trung tâm hoạt động (vùng hoạt động).”"}, {"question": "Ví dụ nào sau đây nói lên tính đặc hiệu của enzyme?", "choices": ["Trong một phút, một phân tử amylase thủy phân được 1 triệu phân tử amylopectin.", "Amylase chỉ thủy phân được tinh bột, không thủy phân được cellulose.", "Amylase bị bất hoạt ở nhiệt độ trên <span class=\"ct\">60°C</span> hoặc dưới <span class=\"ct\">0°C</span>", "Amylase có hoạt tính xúc tác mạnh ở môi trường có pH từ 7 đến 8."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án câu 110: Chọn B. Amylase chỉ thủy phân được tinh bột, không thủy phân được cellulose.</b><br><b><u>Giải thích:</u></b> Ý A thể hiện hoạt tính xúc tác mạnh, ý C thể hiện tính chịu ảnh hưởng bởi nhiệt độ, ý D thể hiện tính chịu ảnh hưởng bởi nồng độ pH."}, {"question": "Điều nào sau đây nhằm giải thích cho tính đặc hiệu cao của enzyme?", "choices": ["Enzyme là chất xúc tác sinh học có bản chất là protein.", "Enzyme chỉ xúc tác cho các phản ứng hóa sinh ở trong tế bào.", "Enzyme chỉ hoạt động tốt nhất trong một điều kiện nhiệt độ, pH thích hợp.", "Trung tâm hoạt động của enzyme cần phải tương thích với cơ chất do nó xúc tác."], "correctIndex": 3, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án câu 111: Chọn D. </b>Trung tâm hoạt động của enzyme cần phải tương thích với cơ chất do nó xúc tác.<br>Giải thích: Theo đoạn thông tin: “Tính đặc hiệu của một enzyme được cho là do sự phù hợp giữa hình dạng của vị trí hoạt động với hình dạng của cơ chất”."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Hiện nay, tổng diện tích rừng ngập mặn ở Việt Nam khoảng 200.000 ha. Với diện tích này, Việt Nam đứng tốp đầu trong các quốc gia có diện tích rừng ngập mặn trên toàn thế giới. Do Việt Nam có khoảng 3260 km đường bờ biển, chạy dọc theo 28 tỉnh và thành phố từ Móng Cái (tỉnh Quảng Ninh) đến Cà Mau. Chạy dọc theo đường bờ biển ấy, có một số khu rừng ngập mặn lớn như: rừng ngập mặn Cần Giờ (TP. Hồ Chí Minh), rừng ngập mặn Rú Chà (tỉnh Thừa Thiên - Huế), rừng ngập mặn nguyên sinh ở Tam Giang (tỉnh Quảng Nam, rừng ngập mặn ở Cà Mau. Nổi bật trong số đó là rừng ngập mặn Cần Giờ với tổng diện tích nên tới khoảng 37.000 ha, được mệnh danh là khu rừng ngập mặn đẹp nhất của khu vực Đông Nam Á Tuy nhiên, diện tích rừng ngập mặn ở Việt Nam đang có nguy cơ bị đe dọa nghiêm trọng do thu hẹp về diện tích vì tình trạng khai thác chặt phá rừng diễn ra một cách khá phổ biến. Ngoài ra, những cơn gió, bão, sóng biển cũng là nguyên nhân làm thu hẹp diện tích rừng ngập mặn. Bên cạnh đó, tình trạng ô nhiễm môi trường cũng gây ảnh hưởng nghiêm trọng đến rừng ngập mặn.<br>(Theo VH (tổng hợp) - https://dangcongsan.vn)", "cauHoi": [{"question": "Rừng ngập mặn Rú Chà thuộc vùng nào của nước ta?", "choices": ["Duyên hải Nam Trung Bộ.", "Bắc Trung Bộ.", "Đông Nam Bộ.", "Đồng bằng sông Cửu Long."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn.</u></b> Đáp án: B. Bắc Trung Bộ. Theo đoạn thông tin: Rừng ngập mặn Rú Chà (tỉnh Thừa Thiên - Huế). Như vậy, rừng ngập mặn này ở vùng Bắc Trung Bộ."}, {"question": "Rừng ngập mặn Cần Giờ - khu rừng ngập mặn đẹp nhất của khu vực Đông Nam Á – chiếm bao nhiêu phần trăm diện tích rừng ngập mặn của Việt Nam?", "choices": ["18,5%.", "15,8%", "16,3%.", "13,6%."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án: A. 18,5%.</b> Giải thích: Diện tích rừng ngập mặn Cần Giờ là 37.000 ha, tổng diện tích rừng ngập mặn của nước ta là 200.000 ha. Như vậy, tỉ lệ rừng ngập mặn Cần Giờ so với cả nước là: 37.000 : 200.000 = 18,5%."}, {"question": "Nguyên nhân về mặt kinh tế - xã hội gây nên tình trạng thu hẹp diện tích rừng ngập mặn của nước ta là", "choices": ["những cơn gió, bão, sóng biển cường độ mạnh.", "tình trạng khai thác, chặt phá diễn ra phổ biến.", "chính sách quy hoạch của chính quyền địa phương.", "tình trạng cát bay, cát chảy diễn ra thường xuyên."], "correctIndex": 1, "explain": "<b>Đáp án: B. tình trạng khai thác, chặt phá diễn ra phổ biến.</b><br><b><u>Hướng dẫn.</u></b> Theo thông tin: Tuy nhiên, diện tích rừng ngập mặn ở Việt Nam đang có nguy cơ bị đe dọa nghiêm trọng do thu hẹp về diện tích vì tình trạng khai thác chặt phá rừng diễn ra một cách khá phổ biến."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117 </b><br>Trong lịch sử dựng nước và giữ nước của dân tộc ta, chiến thắng Điện Biên Phủ là một trong những đỉnh cao chói lọi, một kỳ tích vẻ vang. Trong cuộc kháng chiến chống thực dân Pháp, chiến thắng lịch sử Điện Biên Phủ là chiến thắng vĩ đại nhất, giáng đòn quyết định, tạo bước ngoặt làm thay đổi cục diện chiến tranh, trực tiếp đưa đến việc ký kết Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương. Chiến thắng Điện Biên Phủ đã củng cố niềm tin tưởng vào sự lãnh đạo của Đảng Cộng sản Việt Nam; cổ vũ toàn Đảng, toàn dân, toàn quân chiến đấu dưới lá cờ vẻ vang của Đảng vì độc lập, tự do của Tổ quốc, vì hạnh phúc của nhân dân. Chiến thắng Điện Biên Phủ mang tầm vóc thời đại, góp phần to lớn vào phong trào đấu tranh vì hoà bình, tiến bộ của nhân loại, đây là là chiến thắng chung của các nước trên bán đảo Đông Dương, của phong trào cộng sản và công nhân quốc tế, của phong trào đấu tranh vì hòa bình, tiến bộ xã hội trên toàn thế giới. Chứng minh một chân lý của thời đại: các dân tộc bị áp bức, bị xâm lược nếu có ý chí kiên cường và đường lối đúng đắn, sáng tạo, biết đoàn kết đấu tranh vì độc lập tự do thì dân tộc đó nhất định giành thắng lợi. (Chiến thắng lịch sử Điện Biên Phủ (7/5/1954), https://tulieuvankien.dangcongsan.vn). (Theo Đỗ Thông, https://ct.qdnd.vn/)", "cauHoi": [{"question": "Chiến thắng lịch sử Điện Biên Phủ (1954) đưa tới việc kí kết hiệp định nào?", "choices": ["Hiệp định Giơnevơ về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam.", "Hiệp định Giơnevơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương.", "Hiệp định Pari về chấm dứt chiến tranh, lập lại hòa bình ở miền nam Việt Nam.", "Hiệp định Pari về chấm dứt chiến tranh, lập lại hòa bình ở ba nước Đông Dương."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án: B.</b> Hiệp định Giơnevơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương. Giải thích: Theo đoạn tư liệu “chiến thắng lịch sử Điện Biên Phủ là chiến thắng vĩ đại nhất, giáng đòn quyết định, tạo bước ngoặt làm thay đổi cục diện chiến tranh, trực tiếp đưa đến việc ký kết Hiệp định Giơ-ne-vơ về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương."}, {"question": "Nội dung nào dưới đây KHÔNG chứng tỏ chiến thắng Điện Biên Phủ của nhân dân Việt Nam mang tầm vóc thời đại?", "choices": ["Mở đầu cho sự sụp đổ hệ thống thuộc địa của chủ nghĩa thực dân mới trên thế giới.", "Đập tan mắt xích quan trọng trong hệ thống thuộc địa của chủ nghĩa thực dân cũ.", "Cổ vũ mạnh mẽ các dân tộc thuộc địa trên thế giới đứng lên đấu tranh giành độc lập.", "Chứng minh chân lý các dân tộc thuộc địa hoàn toàn có thể đánh thắng các nước đế quốc."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án: A.</b> Mở đầu cho sự sụp đổ hệ thống thuộc địa của chủ nghĩa thực dân mới trên thế giới. Giải thích: Căn cứ vào đoạn thông tin: Chiến thắng Điện Biên Phủ mang tầm vóc thời đại, góp phần to lớn vào phong trào đấu tranh vì hoà bình, tiến bộ của nhân loại, đây là là chiến thắng chung của các nước trên bán đảo Đông Dương, của phong trào cộng sản và công nhân quốc tế, của phong trào đấu tranh vì hòa bình, tiến bộ xã hội trên toàn thế giới. Chứng minh một chân lý của thời đại: các dân tộc bị áp bức, bị xâm lược nếu có ý chí kiên cường và đường lối đúng đắn, sáng tạo, biết đoàn kết đấu tranh vì độc lập tự do thì dân tộc đó nhất định giành thắng lợi.” Như vậy, đáp án cần chọn là: mở đầu cho sự sụp đổ hệ thống thuộc địa của chủ nghĩa thực dân mới trên thế giới."}, {"question": "Nội dung chính của đoạn thông tin trên là", "choices": ["kết quả của chiến thắng Điện Biên Phủ.", "ý nghĩa của chiến thắng Điện Biên Phủ.", "phản ánh tầm vóc của chiến thắng lịch sử.", "vai trò của chiến thắng Điện Biên Phủ."], "correctIndex": 1, "explain": "<b><u>Hướng dẫn.</u></b> <b>Đáp án: B.</b> ý nghĩa của chiến thắng Điện Biên Phủ. Giải thích: Mỗi đoạn lớn đều nêu lên các ý nghĩa của chiến thắng lịch sử Điện Biên Phủ mang lại cho dân tộc, cho sự lãnh đạo của Đảng và đối với thế giới. Như vậy, nội dung chính của đoạn thông tin là ý nghĩa của chiến thắng Điện Biên Phủ."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Hiệp định Đối tác Kinh tế Toàn diện Khu vực (RCEP) là một hiệp định nhằm mở rộng và làm sâu sắc hơn sự gắn kết giữa ASEAN và Australia, Trung Quốc, Nhật Bản, Hàn Quốc và New Zealand. Tổng các nước tham gia RCEP chiếm khoảng 30% GDP toàn cầu và 30% dân số thế giới. Mục tiêu của Hiệp định RCEP là thiết lập một nền tảng quan hệ đối tác kinh tế hiện đại, toàn diện, chất lượng cao và cùng có lợi, tạo điều kiện thuận lợi cho việc mở rộng thương mại và đầu tư trong khu vực, đồng thời đóng góp vào sự tăng trưởng và phát triển kinh tế toàn cầu. Theo đó, Hiệp định sẽ mang lại cơ hội thị trường và việc làm cho doanh nghiệp và người dân trong khu vực.", "cauHoi": [{"question": "Hiệp định Đối tác Kinh tế Toàn diện Khu vực (RCEP) là thể hiện Hội nhập kinh tế quốc tế cấp độ nào sau đây?", "choices": ["Hội nhập kinh tế khu vực.", "Hội nhập kinh tế song phương.", "Hội nhập kinh tế toàn cầu.", "Hội nhập kinh tế liên minh."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b> Hiệp định RCEP gồm nhiều nước trong cùng một khu vực (châu Á – Thái Bình Dương) → đây là hội nhập kinh tế khu vực. Chọn đáp án: A"}, {"question": "Mục tiêu của Hiệp định RCEP là thiết lập một nền tảng quan hệ đối tác kinh tế như thế nào?", "choices": ["Hiện đại, toàn diện, chất lượng cao và cùng có lợi.", "Cùng phát triển theo con đường chung vận mệnh.", "Xây dựng nền kinh tế sử dụng đồng tiền chung.", "Xây dựng nền kinh tế làm mô hình kiểu mẫu."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b> Đoạn văn nêu rõ mục tiêu là: <i>“thiết lập một nền tảng quan hệ đối tác kinh tế hiện đại, toàn diện, chất lượng cao và cùng có lợi”</i>. Chọn đáp án: A"}, {"question": "Nội dung nào sau đây <b>không</b> phải mục tiêu của Hiệp định RCEP là thiết lập một nền tảng quan hệ đối tác kinh tế như thế nào?", "choices": ["Cùng phát triển theo con đường chung vận mệnh.", "Làm sâu sắc hơn sự gắn kết giữa các nước trong khu vực.", "Mang lại cơ hội việc làm cho người dân trong khu vực.", "Mở rộng thương mại và đầu tư trong khu vực."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b> B, C, D đều đúng với nội dung đoạn văn (tăng gắn kết, tạo việc làm, mở rộng thương mại – đầu tư). A (<i>“cùng phát triển theo con đường chung vận mệnh”</i>) <b>không được nhắc đến</b> trong mục tiêu của RCEP. Chọn đáp án: A"}], "khongXaoTron": true}]};
